const src = $json;
const redactString = (v) => String(v ?? '')
  .replace(/\+?66[-\s]?\d{1,2}[-\s]?\d{3}[-\s]?\d{4}\b/g, '[PHONE]')
  .replace(/\b0\d{1,2}[-\s]?\d{3}[-\s]?\d{4}\b/g, '[PHONE]')
  .replace(/\b[^\s@,;]+@[^\s@,;]+\.[a-z]{2,}\b/gi, '[EMAIL]')
  .replace(/Bearer\s+[^\s]+/gi, 'Bearer [REDACTED]')
  .replace(/\beyJ[A-Za-z0-9_-]{10,}\.[A-Za-z0-9_-]+\.[A-Za-z0-9_-]+/g, '[JWT]')
  .replace(/\b\d[-\s]?\d{4}[-\s]?\d{5}[-\s]?\d{2}[-\s]?\d\b/g, '[NATIONAL_ID]')
  .replace(/U[a-fA-F0-9]{20,}/g, '[LINE_USER]');
const actualError = src.execution?.error ?? src.error ?? {};
const message = actualError.message ?? actualError.description ?? actualError.cause?.message ?? 'n8n execution failed';
return [{ json: { payload: { executionId: src.execution?.id ?? null, workflow: src.workflow?.name ?? 'unknown', node: src.execution?.lastNodeExecuted ?? null, message: redactString(message) } } }];

const crypto = require('crypto');
const body = JSON.stringify($json.payload);
const ts = Math.floor(Date.now() / 1000);
const signature = 'sha256=' + crypto.createHmac('sha256', $env.INTERNAL_HMAC_SECRET).update(`${body}.${ts}`).digest('hex');
return [{ json: { body, headers: { 'content-type': 'application/json', 'x-signature': signature, 'x-timestamp': String(ts) } } }];
